"""Beginner filtering sequence for the CML3113 ungraded Week 6 practical."""
import copy,json,contextlib,io,os,tempfile,shutil
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def text(title,body,notes):return dict(kind='explanation',title=title,body=body,notes=notes)
def code(title,source,notes):return dict(kind='code',title=title,body='',code=source,practice_code=source,code_size=25,caption='Use the supplied engineering_data.csv. Run cells in order.',explain=[],notes=notes)
def apply():
 p=ROOT/'data/iuea_deck_content.json';decks=json.loads(p.read_text());d=next(d for d in decks if d['cohort']=='CML3113' and d['week']==6)
 if d.get('beginner_filtering_revision'):return
 old=copy.deepcopy(d['slides']);at=lambda n:copy.deepcopy(old[n-1])
 new=[at(1),text('Today: clean, check and explain','Inspect the CSV → remove duplicate observations → keep valid rows → fill missing temperatures → summarise → plot.\n\nA6 and Quiz 6 are waived for CML3113. This lesson is ungraded practice; no upload or quiz response is required.','The aim is to understand each cleaning decision. Learners save their practice in Drive. A6 and Quiz 6 do not contribute to coursework marks; earlier submissions remain preserved. This waiver does not cancel other assessments.'),at(3),at(4),at(5),text('Two names for two tables','raw_data: the original table read from the CSV.\n\ncleaned_data: a separate working table that we will change.','Names are labels chosen by us, not special Python words. raw_data lets us check what was originally recorded; cleaned_data will hold the result of each cleaning step. Do not call every table data because we need to distinguish them.'),at(7)]
 new += [text('A missing value is not zero','NaN means a value is missing. A measured zero is still a recorded value.\n\nisna() asks “is this cell missing?” It returns True for yes and False for no.','Read True as yes and False as no. For a whole table isna gives an answer for each cell. sum counts the True answers down each column: True counts as 1 and False as 0. A missing crusher-energy measurement is not evidence that energy consumption was zero.'),code('Count missing cells in each column','print(raw_data.isna().sum())','Read each output label as a column name and its number as the count of missing cells. This inspects the data; it does not change any value.'),text('Find a repeated observation','record_id identifies one observation. equipment_id identifies the equipment and may repeat.\n\nduplicated("record_id") marks later copies True. The first occurrence is False.','For IDs 1, 2, 1 the answers are False, False, True. We mark the last occurrence because our stated rule keeps the first. The supplied CSV has one later copy of record ID 1. Repeated equipment labels are normal.'),code('Count repeated record IDs','is_repeated_record = raw_data.duplicated("record_id")\nprint(is_repeated_record)\nprint(is_repeated_record.sum())','The variable holds one True/False answer for every row. print shows row labels on the left and answers on the right; a long Series may show only its beginning and end. sum counts the True answers: one duplicate observation. This has not removed it.'),text('Remove the later copy; keep the original','drop_duplicates("record_id") keeps the first occurrence of each record ID.\n\n.copy() makes an independent working table. len(table) counts its rows.','Finding and removing are different actions: duplicated answers a question; drop_duplicates returns a table without later copies. Read the next chain left to right. The original raw_data table stays at 91 rows.'),code('Create the working table','cleaned_data = raw_data.drop_duplicates("record_id").copy()\nprint(len(raw_data))\nprint(len(cleaned_data))','First remove later record-ID duplicates, then copy that result into cleaned_data. The two lines print 91 original rows and 90 working rows. No missing value has been filled yet.')]
 new += [text('Question 1: is the target recorded?','cleaned_data["target"] selects the target column.\n\n.notna() asks whether each value is present. It returns True for a recorded value and False for a missing value.','Target is crusher energy in kWh/t. We cannot use a missing target as an observed outcome. notna means NOT missing, the opposite of isna. A recorded target of zero would count as present. The next example only creates answers; it does not delete rows.'),code('Look at the values, then their answers','target_is_recorded = cleaned_data["target"].notna()\nprint(cleaned_data["target"].head())\nprint(target_is_recorded.head())','Match the row labels across the two printed columns. Records 1, 2 and 3 have targets, so their answers are True. Record 4 (row label 3) has NaN and answers False. Record 5 is recorded and answers True. The row label is a position label, not the record_id. No rows have been removed here.'),text('Use the answers to select rows','cleaned_data[target_is_recorded] keeps rows whose answer is True. Rows answering False are left out of the returned table.\n\nThis True/False selection is called a Boolean mask. The variable name does not need to end in _mask.','Distinguish brackets with a quoted column name from brackets with a True/False Series. The first selects a column; the second selects rows. Use answers produced from this same working table so row labels align. Creating the answers and using them to select rows are separate steps.'),code('Try one condition on its own','rows_with_target = cleaned_data[target_is_recorded].copy()\nprint(len(cleaned_data))\nprint(len(rows_with_target))','There are 90 rows before selection and 89 with recorded targets. rows_with_target is a demonstration copy. cleaned_data remains at 90 rows so we can compare two independent conditions on the same rows next.'),text('Question 2: is the load valid?','load_pct is a percentage. For this exercise the valid range is 0 through 100, including both endpoints.\n\n.between(0, 100) answers True inside that range and False outside it.','Read the endpoints as included: 0 and 100 pass; -5 and 101 fail. The supplied file contains load -5 for record ID 9. We reject that observation under this stated cleaning rule rather than silently changing its reading.'),code('Inspect the load answers','load_is_valid = cleaned_data["load_pct"].between(0, 100)\nprint(cleaned_data["load_pct"].head(10))\nprint(load_is_valid.head(10))','head(10) shows up to ten rows, rather than the default five. Compare matching row labels. Record ID 9 has load -5 and its answer is False. This still only computes answers; cleaned_data has not changed.')]
 new += [text('Keep a row only when both answers are True','& means “and” for two True/False columns.\n\nTrue & True → True. Any pair containing False → False.\n\nOur rule: a recorded target AND a valid load.','Python and is not the operator for combining pandas Series; use &. Both answer columns here come from the same cleaned_data table. Named conditions avoid nesting several expressions on one line. If writing comparisons directly, place each comparison in parentheses.'),dict(kind='table',title='Which observations will we keep?',body='',table=[['Record ID','Target recorded?','Load valid?','Keep?'],['1','True','True','Yes'],['4','False','True','No'],['9','True','False','No']],notes='These three record IDs are from the supplied CSV. Record 1 has target 14.001 and load 59.15, so both checks pass. Record 4 has no target, although load 75.98 is valid. Record 9 has target 13.908, but load -5 fails. A row needs BOTH conditions. This is a selected illustration, not the entire 90-row table.'),code('Combine the answers, then keep those rows','rows_to_keep = target_is_recorded & load_is_valid\nprint(rows_to_keep.sum())\ncleaned_data = cleaned_data[rows_to_keep].copy()\nprint(len(cleaned_data))','Line 1 combines matching answers without changing the table. Line 2 counts the True answers: 88. Line 3 keeps only those rows and makes the result the new working table. Line 4 confirms 88 retained rows. From 91 original rows we removed one later duplicate, one missing target, and one invalid load.'),text('Fill only missing ambient temperatures','ambient_c is temperature in °C. .median() finds the middle of the recorded values in the retained rows.\n\n.fillna(value) replaces only missing entries. Assign the result back to the ambient_c column.','Compute this after removing invalid observations, so discarded rows do not influence the replacement. For an even count, median averages the two central values. pandas skips missing values for median. We fill ambient temperature only; we do not invent missing targets. round(value, 3) changes the displayed precision, not our saved median. float converts the value to a Python decimal number for display.'),at(18)]
 # Retain the established summaries and plots, with corrected practice-only wording.
 for n in range(22,32):
  s=at(n)
  if n==22:s['body']='mean, min and max summarise a numeric column. groupby collects rows with the same equipment label before calculating.\n\nUse the cleaned table for summaries and charts.'
  new.append(s)
 new += [text('Optional extension: check numeric text','The main cleaning and charting walkthrough is complete. Continue here only if time permits.\n\nSometimes a numeric column contains text that cannot be converted to a number. The following check distinguishes that problem from an existing blank.','This extension is ungraded and is not required to complete today’s core practice. The supplied CSV has no invalid numeric text; the expected conversion-failure count is zero. Reuse raw_data to inspect the original entries.'),at(20)]
 s=at(21)
 for key in ('code','practice_code','notes'):
  s[key]=s[key].replace('was_recorded_mask','value_was_recorded').replace('conversion_failed_mask','conversion_failed')
 new.append(s)
 new += [text('Optional extension: put steps in a function','A function gives a reusable calculation a name. Its body runs when the function is called.\n\nThe next example calculates mean load for each equipment group; it is practice, not an A6 requirement.','Explain parameters as inputs and return as the result passed back to the caller. records is a list of row dictionaries. pd.DataFrame turns those rows into a labelled table. Learners can revisit this after understanding the cleaning workflow.'),at(33),at(34),at(35),at(39),at(40),at(42),at(43)]
 d['slides']=new;d['beginner_filtering_revision']='2026-10-20';d['pandas_explanations_revision']=False
 # Run all examples against the issued data and attach actual outputs to the matching notes.
 previous=Path.cwd()
 with tempfile.TemporaryDirectory() as tmp:
  shutil.copy(ROOT/'IUEA_Teaching_Plan/assessment_banks/W06/CML3113/A/engineering_data.csv',tmp);os.chdir(tmp);ns={}
  try:
   for i,s in enumerate(new,1):
    s['sequence_number']=i
    if s.get('practice_code'):
     out=io.StringIO()
     with contextlib.redirect_stdout(out):exec(s['practice_code'],ns)
     s['notes']+='\n\nVerified output from the supplied CSV\n'+out.getvalue().strip()
   assert len(ns['raw_data'])==91 and len(ns['cleaned_data'])==88
   assert not ns['cleaned_data'].isna().any().any()
   assert abs(ns['median_ambient_c']-26.07)<1e-9
   assert ns['raw_data']['target'].isna().sum()==1
  finally:os.chdir(previous)
 notes=ROOT/'IUEA_Teaching_Plan/decks/lecturer_notes'/Path(d['filename']).with_suffix('.md')
 notes.write_text('# CML3113 Week 6 — ungraded practical\n\n'+'\n\n'.join(f"## Slide {i}: {s['title']}\n\n{s['notes']}" for i,s in enumerate(new,1)))
 p.write_text(json.dumps(decks,ensure_ascii=False,indent=2)+'\n');print('Updated',len(new),'slides; verified cleaning 91 → 88 and median 26.07.')
if __name__=='__main__':apply()
